module frog_escape (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] d,\n    input [7:0] l0, w0, h0,\n    input [7:0] l1, w1, h1,\n    input [7:0] l2, w2, h2,\n    input [7:0] l3, w3, h3,\n    input [7:0] l4, w4, h4,\n    input [7:0] l5, w5, h5,\n    input [7:0] l6, w6, h6,\n    input [7:0] l7, w7, h7,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // Frog storage arrays\n    reg [7:0] l [0:7];\n    reg [7:0] w [0:7];\n    reg [7:0] h [0:7];\n    \n    // Escape status flags\n    reg [7:0] escapable;\n    \n    // State machine\n    reg [2:0] state;\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] STORE_INPUTS  = 3'd1;\n    localparam [2:0] CHECK_DIRECT  = 3'd2;\n    localparam [2:0] CHECK_PAIRS   = 3'd3;\n    localparam [2:0] CHECK_TRIPLES = 3'd4;\n    localparam [2:0] COUNT         = 3'd5;\n    localparam [2:0] FINISH        = 3'd6;\n    \n    // Loop counters\n    reg [2:0] i, j, k;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 8'd0;\n            done <= 1'b0;\n            escapable <= 8'd0;\n            i <= 3'd0;\n            j <= 3'd0;\n            k <= 3'd0;\n            // Initialize arrays with for-loop\n            begin : init_arrays\n                integer idx;\n                for (idx = 0; idx < 8; idx = idx + 1) begin\n                    l[idx] <= 8'd0;\n                    w[idx] <= 8'd0;\n                    h[idx] <= 8'd0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    escapable <= 8'd0;\n                    i <= 3'd0;\n                    j <= 3'd0;\n                    k <= 3'd0;\n                    if (start) begin\n                        state <= STORE_INPUTS;\n                    end\n                end\n\n                STORE_INPUTS: begin\n                    l[0] <= l0; l[1] <= l1; l[2] <= l2; l[3] <= l3;\n                    l[4] <= l4; l[5] <= l5; l[6] <= l6; l[7] <= l7;\n                    w[0] <= w0; w[1] <= w1; w[2] <= w2; w[3] <= w3;\n                    w[4] <= w4; w[5] <= w5; w[6] <= w6; w[7] <= w7;\n                    h[0] <= h0; h[1] <= h1; h[2] <= h2; h[3] <= h3;\n                    h[4] <= h4; h[5] <= h5; h[6] <= h6; h[7] <= h7;\n                    state <= CHECK_DIRECT;\n                end\n\n                CHECK_DIRECT: begin\n                    if (l[i] > d) begin\n                        escapable[i] <= 1'b1;\n                    end\n                    \n                    if (i < 3'd7) begin\n                        i <= i + 3'd1;\n                    end else begin\n                        i <= 3'd0;\n                        state <= CHECK_PAIRS;\n                    end\n                end\n\n                CHECK_PAIRS: begin\n                    if (i != j) begin\n                        if (w[i] < w[j] && (h[j] + l[i]) > d) begin\n                            escapable[i] <= 1'b1;\n                        end\n                    end\n                    \n                    if (j < 3'd7) begin\n                        j <= j + 3'd1;\n                    end else begin\n                        j <= 3'd0;\n                        if (i < 3'd7) begin\n                            i <= i + 3'd1;\n                        end else begin\n                            i <= 3'd0;\n                            j <= 3'd1;\n                            k <= 3'd2;\n                            state <= CHECK_TRIPLES;\n                        end\n                    end\n                end\n\n                CHECK_TRIPLES: begin\n                    if (i != j && i != k && j != k) begin\n                        if (w[i] < w[j] && w[j] < w[k] && (h[k] + h[j] + l[i]) > d) begin\n                            escapable[i] <= 1'b1;\n                        end\n                    end\n                    \n                    if (k < 3'd7) begin\n                        k <= k + 3'd1;\n                    end else begin\n                        k <= 3'd0;\n                        if (j < 3'd6) begin\n                            j <= j + 3'd1;\n                            k <= j + 3'd1;\n                        end else begin\n                            j <= 3'd0;\n                            if (i < 3'd5) begin\n                                i <= i + 3'd1;\n                                j <= i + 3'd1;\n                                k <= j + 3'd1;\n                            end else begin\n                                state <= COUNT;\n                            end\n                        end\n                    end\n                end\n\n                COUNT: begin\n                    result <= escapable[0] + escapable[1] + escapable[2] + escapable[3]\n                            + escapable[4] + escapable[5] + escapable[6] + escapable[7];\n                    state <= FINISH;\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule